642	 * unknown, or the session has expired. Callers that need a hard failure use
643	 * `getActor()` in `@/lib/actor` instead.
644	 */
645	export async function getSessionPrincipal(): Promise<SessionPrincipal | null> {
646	  const token = await getSessionToken();
647	  if (token === null) return null;
648	
649	  const principal = await resolveSession(token);
650	  if (principal === null) return null;
651	
652	  return parseIso(principal.expiresAt).getTime() > Date.now() ? principal : null;
653	}
654	
655	export async function setSessionCookie(
656	  token: string,
657	  expiresAt: IsoTimestamp,
658	): Promise<void> {
659	  const jar = await cookies();
660	  jar.set(SESSION_COOKIE_NAME, token, {
661	    httpOnly: true,
662	    sameSite: "lax",
663	    secure: process.env.NODE_ENV === "production",
664	    path: "/",
665	    expires: parseIso(expiresAt),
666	  });
667	}
668	
669	export async function clearSessionCookie(): Promise<void> {
670	  const jar = await cookies();
671	  jar.delete(SESSION_COOKIE_NAME);
672	}
