715	/** Groups a feed page by calendar day, newest day first. */
716	export function groupByDay(
717	  events: readonly ActivityEvent[],
718	): readonly ActivityGroup[] {
719	  const byDay = new Map<string, ActivityEvent[]>();
720	
721	  for (const event of events) {
722	    const day = event.occurredAt.slice(0, 10);
723	    const bucket = byDay.get(day) ?? [];
