965	export async function login(
966	  input: LoginInput,
967	): Promise<{ user: User; token: string }> {
968	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, LOGIN_BUCKET);
969	  if (!verdict.allowed) {
970	    throw new Error("Too many sign-in attempts; try again shortly");
971	  }
972	
973	  const user = await userRepo.findUserByEmail(input.email);
974	  if (!user) throw new Error("Those credentials did not match");
975	
976	  const storedHash = await userRepo.findPasswordHash(user.id);
977	  if (!storedHash || !(await verifyPassword(input.password, storedHash))) {
978	    throw new Error("Those credentials did not match");
979	  }
980	
981	  const { token } = await createSessionToken(user.id);
982	
983	  return { user, token };
984	}
