new='''const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * True once a deleted organization's grace period is over at `now`: from
 * `DELETED_WORKSPACE_RETENTION_DAYS × 24h` after the deletion the workspace
 * is gone for good, whether or not the retention sweep has purged it yet.
 * A live organization never expires.
 *
 * The restore guard and the purge both ask this one question, so the instant
 * a workspace stops being restorable is the instant it becomes purgeable.
 */
export function isPastDeletionWindow(
  org: Pick<Organization, "archivedAt">,
  now: Date,
): boolean {
  if (org.archivedAt === null) return false;

  const deletedAt = new Date(org.archivedAt).getTime();
  return (
    now.getTime() - deletedAt >= DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY
  );
