/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 *
 * It opens a grace period rather than destroying anything: the workspace is
 * kept, inert, for `DELETED_WORKSPACE_RETENTION_DAYS` days, during which its
 * owner can `restoreOrganization` it; after that the retention sweep purges
 * it.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  assertNotArchived("Organization", org.id, org);

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  const deleted = await orgRepo.archiveOrg(input.orgId);

  await emit("organization.deleted", {
    ...actorEnvelope(actor),
    slug: deleted.slug,
  });

  return deleted;
}

/**
 * Brings a deleted organization back while its grace period is still open.
 *
 * Takes a bare user id: no `Actor` can be resolved for a deleted workspace —
 * nobody can sign in to it — so the membership is looked up here and the
 * `org:restore` decision is made against the role it carries.
 *
 * To anyone who is not a member the workspace does not exist, and once the
 * window has closed it does not exist for anybody, purged or not; both are a
 * `NotFoundError` so the answer never reveals which of the two it was.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) throw new NotFoundError("Organization", orgId);

  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Organization", orgId);
  }

  if (isPastDeletionWindow(org, new Date())) {
    throw new NotFoundError("Organization", orgId);
  }

  const actor: Actor = { userId, orgId: org.id, role: member.role };
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:restore", orgResource(orgId));

  if (!isArchived(org)) return org;

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...envelope(restored.id, userId),
    slug: restored.slug,
  });

  return restored;
}

