/**
 * Deleting a workspace: a grace period, then a purge.
 *
 * A deleted workspace is kept, inert, for `DELETED_WORKSPACE_RETENTION_DAYS`
 * days. Its owner can restore it inside that window; once the window has
 * closed it is gone, and the retention sweep removes every trace of it.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { DELETED_WORKSPACE_RETENTION_DAYS } from "@/config/constants";
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError, ROLE_MATRIX } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { activityActionSchema } from "@/schemas/activity";
import { getDb } from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runDigestEmailJob } from "@/server/jobs/digest-email-job";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { NotFoundError } from "@/server/services/_support";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import { acceptInvitation } from "@/server/services/invitation-service";
import { notify } from "@/server/services/notification-service";
import {
  createOrganization,
  deleteOrganization,
  listOrganizationsForUser,
  restoreOrganization,
} from "@/server/services/organization-service";
import { resolveActorForOrg, switchActiveOrg } from "@/server/services/session-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { IsoTimestamp, OrgId, SessionId, UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { SessionPrincipal } from "@/types/member";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const WINDOW_MS = DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;
const PAST = "2026-01-01T00:00:00.000Z";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function principalFor(userId: UserId): SessionPrincipal {
  return {
    userId,
    email: "someone@example.test",
    activeOrgId: null,
    expiresAt: toIsoTimestamp(new Date(Date.now() + MS_PER_DAY)),
  };
}

async function remove(tenant: Tenant) {
  return deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
}

/** When the stored deletion stamp says the workspace was deleted. */
async function deletedAt(orgId: OrgId): Promise<Date> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org || org.archivedAt === null) throw new Error("not deleted");
  return new Date(org.archivedAt);
}

/** Row counts of every table that carries an `org_id`, for one workspace. */
function rowsOf(orgId: OrgId): Record<string, number> {
  const client = getDb().$client;
  const tables = client
    .prepare(
      "SELECT m.name AS name FROM sqlite_master m JOIN pragma_table_info(m.name) c ON c.name = 'org_id' WHERE m.type = 'table'",
    )
    .all() as readonly { name: string }[];

  const counts: Record<string, number> = {};
  for (const { name } of tables) {
    const row = client
      .prepare(`SELECT count(*) AS n FROM "${name}" WHERE org_id = ?`)
      .get(orgId) as { n: number };
    counts[name] = row.n;
  }
  return counts;
}

/** A full dump of everything a workspace owns, to prove nothing moved. */
function snapshot(orgId: OrgId): string {
  const client = getDb().$client;
  const dump: Record<string, unknown> = {
    organization: client.prepare("SELECT * FROM organizations WHERE id = ?").all(orgId),
  };
  for (const name of Object.keys(rowsOf(orgId)).sort()) {
    dump[name] = client
      .prepare(`SELECT * FROM "${name}" WHERE org_id = ? ORDER BY rowid`)
      .all(orgId);
  }
  return JSON.stringify(dump);
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

describe("the vocabulary", () => {
  it("has an owner-only org:restore action and the two audit actions", () => {
    expect(ROLE_MATRIX["org:restore"]).toBe("owner");
    expect(activityActionSchema.parse("organization.deleted")).toBe("organization.deleted");
    expect(activityActionSchema.parse("organization.restored")).toBe("organization.restored");
    expect(DELETED_WORKSPACE_RETENTION_DAYS).toBe(30);
  });
});

describe("deleting a workspace", () => {
  it("publishes organization.deleted and refuses to delete twice", async () => {
    const tenant = await createTenant("del-once");
    const seen = capture("organization.deleted");

    const deleted = await remove(tenant);

    expect(deleted.archivedAt).not.toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      slug: "del-once",
    });

    await expect(remove(tenant)).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(seen).toHaveLength(1);
  });

  it("keeps its guards and its typed confirmation", async () => {
    const tenant = await createTenant("del-guards");

    await expect(
      deleteOrganization(tenant.actors.admin, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: "something-else",
      }),
    ).rejects.toThrow(/confirmation/);

    expect((await orgRepo.findOrgById(tenant.org.id))?.archivedAt).toBeNull();
  });

  it("locks everyone out, hides it, and keeps its name reserved", async () => {
    const tenant = await createTenant("del-hidden");
    await remove(tenant);

    const principal = principalFor(tenant.userIds.owner);
    await expect(resolveActorForOrg(principal, "del-hidden")).resolves.toBeNull();
    await expect(
      switchActiveOrg(principal, { orgId: tenant.org.id }),
    ).rejects.toThrow();
    await expect(listOrganizationsForUser(tenant.userIds.owner)).resolves.toEqual([]);

    const other = await createOrganization(tenant.userIds.admin, {
      name: "Squatter",
      slug: "del-hidden",
      plan: "free",
    });
    expect(other.slug).not.toBe("del-hidden");
  });
});

describe("while a workspace is deleted", () => {
  it("creates no notifications, from notify() or from the fan-out", async () => {
    const tenant = await createTenant("del-quiet");
    const issue = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, {
        assigneeId: tenant.userIds.member,
      }),
      tenant.userIds.owner,
      1,
    );
    await remove(tenant);

    const payload = { title: "t", body: "b", href: "/x", actorId: null };
    await expect(
      notify(tenant.org.id, "issue_assigned", [tenant.userIds.member], payload),
    ).resolves.toEqual([]);

    await emit("issue.assigned", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      occurredAt: toIsoTimestamp(new Date()),
      issueId: issue.id,
      projectId: tenant.project.id,
      previousAssigneeId: null,
      assigneeId: tenant.userIds.member,
    });

    expect(rowsOf(tenant.org.id).notifications).toBe(0);

    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    await expect(
      notify(tenant.org.id, "issue_assigned", [tenant.userIds.member], payload),
    ).resolves.toHaveLength(1);
  });

  it("refuses a pending invitation, which stays pending", async () => {
    const tenant = await createTenant("del-invite");
    const invitation = await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "new@del-invite.test", role: "member", expiresInDays: 7 },
      tenant.userIds.owner,
      hashToken("del-invite-token"),
    );
    const invitee = await userRepo.insertUser({
      email: "new@del-invite.test",
      name: "Invitee",
      passwordHash: "seed",
    });
    await remove(tenant);

    await expect(
      acceptInvitation(invitee.id, { token: "del-invite-token" }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const pending = await invitationRepo.listPendingInvitations(tenant.org.id);
    expect(pending.map((row) => row.id)).toEqual([invitation.id]);
    await expect(memberRepo.findMember(tenant.org.id, invitee.id)).resolves.toBeNull();

    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    const member = await acceptInvitation(invitee.id, { token: "del-invite-token" });
    expect(member.orgId).toBe(tenant.org.id);
  });

  it("is left alone by every background job", async () => {
