describe("purging", () => {
  it("removes every trace once the window has closed, and only then", async () => {
    const doomed = await createTenant("purge-me");
    const recent = await createTenant("purge-recent");
    const live = await createTenant("purge-live");
    // No usage counters for `doomed`: the purge must not depend on them.
    await usageRepo.recomputeUsage(recent.org.id);
    await usageRepo.recomputeUsage(live.org.id);
    await notifyOnce(doomed);
    await issueRepo.insertIssue(
      issueInput(doomed.org.id, doomed.project.id),
      doomed.userIds.owner,
      1,
    );
    await sessionRepo.createSession(
      doomed.userIds.owner,
      "purge-session-hash",
      toIsoTimestamp(new Date(Date.now() + 400 * MS_PER_DAY)),
    );
    const session = getDb()
      .$client.prepare("SELECT id FROM sessions WHERE token_hash = ?")
      .get("purge-session-hash") as { id: string };
    await sessionRepo.setActiveOrg(session.id as SessionId, doomed.org.id);

    await remove(doomed);
    const at = await deletedAt(doomed.org.id);
    getDb()
      .$client.prepare("UPDATE organizations SET archived_at = ? WHERE id = ?")
      .run(new Date(at.getTime() + 1_000).toISOString(), recent.org.id);
    const liveBefore = snapshot(live.org.id);
    const recentBefore = snapshot(recent.org.id);

    await runCleanupArchivedJob(new Date(at.getTime() + WINDOW_MS - 1));
    expect(await orgRepo.findOrgById(doomed.org.id)).not.toBeNull();

    await runCleanupArchivedJob(new Date(at.getTime() + WINDOW_MS));

    await expect(orgRepo.findOrgById(doomed.org.id)).resolves.toBeNull();
    expect(Object.values(rowsOf(doomed.org.id)).every((n) => n === 0)).toBe(true);
    expect(snapshot(recent.org.id)).toBe(recentBefore);
    expect(snapshot(live.org.id)).toBe(liveBefore);

    // Accounts survive; the session just has no active workspace any more.
    await expect(userRepo.findUserById(doomed.userIds.owner)).resolves.not.toBeNull();
    const principal = await sessionRepo.findSessionByTokenHash("purge-session-hash");
    expect(principal).toMatchObject({ userId: doomed.userIds.owner, activeOrgId: null });

    await expect(
      restoreOrganization(doomed.userIds.owner, doomed.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const reborn = await createOrganization(doomed.userIds.owner, {
      name: "Reborn",
      slug: "purge-me",
      plan: "free",
    });
    expect(reborn.slug).toBe("purge-me");
    expect(reborn.id).not.toBe(doomed.org.id);
  });
});

