 * Deleting a workspace: a grace period, then a purge.
 *
 * A deleted workspace is kept, inert, for `DELETED_WORKSPACE_RETENTION_DAYS`
 * days. Its owner can restore it inside that window; once the window has
 * closed it is gone, and the retention sweep removes every trace of it.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

