const MS_PER_DAY = 24 * 60 * 60 * 1000;
const WINDOW_MS = DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;
const PAST = "2026-01-01T00:00:00.000Z";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function principalFor(userId: UserId): SessionPrincipal {
  return {
    userId,
    email: "someone@example.test",
    activeOrgId: null,
    expiresAt: toIsoTimestamp(new Date(Date.now() + MS_PER_DAY)),
  };
}

async function remove(tenant: Tenant) {
  return deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
}

/** When the stored deletion stamp says the workspace was deleted. */
async function deletedAt(orgId: OrgId): Promise<Date> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org || org.archivedAt === null) throw new Error("not deleted");
  return new Date(org.archivedAt);
}

/** Row counts of every table that carries an `org_id`, for one workspace. */
function rowsOf(orgId: OrgId): Record<string, number> {
  const client = getDb().$client;
  const tables = client
    .prepare(
      "SELECT m.name AS name FROM sqlite_master m JOIN pragma_table_info(m.name) c ON c.name = 'org_id' WHERE m.type = 'table'",
    )
    .all() as readonly { name: string }[];

  const counts: Record<string, number> = {};
  for (const { name } of tables) {
    const row = client
      .prepare(`SELECT count(*) AS n FROM "${name}" WHERE org_id = ?`)
      .get(orgId) as { n: number };
    counts[name] = row.n;
  }
  return counts;
}

/** A full dump of everything a workspace owns, to prove nothing moved. */
function snapshot(orgId: OrgId): string {
  const client = getDb().$client;
  const dump: Record<string, unknown> = {
    organization: client.prepare("SELECT * FROM organizations WHERE id = ?").all(orgId),
  };
  for (const name of Object.keys(rowsOf(orgId)).sort()) {
    dump[name] = client
      .prepare(`SELECT * FROM "${name}" WHERE org_id = ? ORDER BY rowid`)
      .all(orgId);
  }
  return JSON.stringify(dump);
}

