describe("the vocabulary", () => {
  it("has an owner-only org:restore action and the two audit actions", () => {
    expect(ROLE_MATRIX["org:restore"]).toBe("owner");
    expect(activityActionSchema.parse("organization.deleted")).toBe("organization.deleted");
    expect(activityActionSchema.parse("organization.restored")).toBe("organization.restored");
    expect(DELETED_WORKSPACE_RETENTION_DAYS).toBe(30);
  });
});

describe("deleting a workspace", () => {
  it("publishes organization.deleted and refuses to delete twice", async () => {
    const tenant = await createTenant("del-once");
    const seen = capture("organization.deleted");

    const deleted = await remove(tenant);

    expect(deleted.archivedAt).not.toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      slug: "del-once",
    });

    await expect(remove(tenant)).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(seen).toHaveLength(1);
  });

  it("keeps its guards and its typed confirmation", async () => {
    const tenant = await createTenant("del-guards");

    await expect(
      deleteOrganization(tenant.actors.admin, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: "something-else",
      }),
    ).rejects.toThrow(/confirmation/);

    expect((await orgRepo.findOrgById(tenant.org.id))?.archivedAt).toBeNull();
  });

  it("locks everyone out, hides it, and keeps its name reserved", async () => {
    const tenant = await createTenant("del-hidden");
    await remove(tenant);

    const principal = principalFor(tenant.userIds.owner);
    await expect(resolveActorForOrg(principal, "del-hidden")).resolves.toBeNull();
    await expect(
      switchActiveOrg(principal, { orgId: tenant.org.id }),
    ).rejects.toThrow();
    await expect(listOrganizationsForUser(tenant.userIds.owner)).resolves.toEqual([]);

    const other = await createOrganization(tenant.userIds.admin, {
      name: "Squatter",
      slug: "del-hidden",
      plan: "free",
    });
    expect(other.slug).not.toBe("del-hidden");
  });
});

describe("while a workspace is deleted", () => {
  it("creates no notifications, from notify() or from the fan-out", async () => {
    const tenant = await createTenant("del-quiet");
    const issue = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, {
        assigneeId: tenant.userIds.member,
      }),
      tenant.userIds.owner,
      1,
    );
    await remove(tenant);

    const payload = { title: "t", body: "b", href: "/x", actorId: null };
    await expect(
      notify(tenant.org.id, "issue_assigned", [tenant.userIds.member], payload),
    ).resolves.toEqual([]);

    await emit("issue.assigned", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      occurredAt: toIsoTimestamp(new Date()),
      issueId: issue.id,
      projectId: tenant.project.id,
      previousAssigneeId: null,
      assigneeId: tenant.userIds.member,
    });

    expect(rowsOf(tenant.org.id).notifications).toBe(0);

    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    await expect(
      notify(tenant.org.id, "issue_assigned", [tenant.userIds.member], payload),
    ).resolves.toHaveLength(1);
  });

  it("refuses a pending invitation, which stays pending", async () => {
    const tenant = await createTenant("del-invite");
    const invitation = await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "new@del-invite.test", role: "member", expiresInDays: 7 },
      tenant.userIds.owner,
      hashToken("del-invite-token"),
    );
    const invitee = await userRepo.insertUser({
      email: "new@del-invite.test",
      name: "Invitee",
      passwordHash: "seed",
    });
    await remove(tenant);

    await expect(
      acceptInvitation(invitee.id, { token: "del-invite-token" }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const pending = await invitationRepo.listPendingInvitations(tenant.org.id);
    expect(pending.map((row) => row.id)).toEqual([invitation.id]);
    await expect(memberRepo.findMember(tenant.org.id, invitee.id)).resolves.toBeNull();

    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    const member = await acceptInvitation(invitee.id, { token: "del-invite-token" });
    expect(member.orgId).toBe(tenant.org.id);
  });

  it("is left alone by every background job", async () => {
    const tenant = await createTenant("del-jobs", "growth");
    const issue = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, {
        assigneeId: tenant.userIds.member,
        dueAt: PAST,
      }),
      tenant.userIds.owner,
      1,
    );
    await usageRepo.recomputeUsage(tenant.org.id);
    getDb()
      .$client.prepare(
        "UPDATE subscriptions SET status = 'trialing', current_period_end = ? WHERE org_id = ?",
      )
      .run(PAST, tenant.org.id);
    const endpoint = await webhookRepo.insertEndpoint(
      { orgId: tenant.org.id, url: "https://example.test/hook", eventTypes: ["issue.created"] },
      "secret",
    );
    const delivery = await webhookRepo.enqueueDelivery(
      tenant.org.id,
      endpoint.id,
      "issue.created",
      "{}",
    );

    await remove(tenant);
    const before = snapshot(tenant.org.id);
    const overdue = capture("issue.overdue");
    const planChanges = capture("billing.plan_changed");

    const now = new Date(Date.now() + MS_PER_DAY);
    expect(await usageRepo.listOrgIdsForRollup(1_000)).not.toContain(tenant.org.id);
    await runOverdueIssueJob(now);
    await runDigestEmailJob(now);
    await runUsageRollupJob(now);
    await runTrialExpiryJob(now);
    await runCleanupArchivedJob(new Date(Date.now() + WINDOW_MS - 60_000));

    expect(overdue).toEqual([]);
    expect(planChanges).toEqual([]);
    expect(snapshot(tenant.org.id)).toBe(before);

    await runWebhookDeliveryJob(now);
    const failed = getDb()
      .$client.prepare("SELECT status FROM webhook_deliveries WHERE id = ?")
      .get(delivery.id) as { status: string };
    expect(failed.status).toBe("failed");

    // …and a restore switches all of it back on.
    await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(await usageRepo.listOrgIdsForRollup(1_000)).toContain(tenant.org.id);
    await runOverdueIssueJob(now);
    await runTrialExpiryJob(now);
    expect(overdue.map((payload) => payload.issueId)).toEqual([issue.id]);
    expect(planChanges.map((payload) => payload.orgId)).toEqual([tenant.org.id]);
  });
});

describe("restoring a workspace", () => {
  it("brings it back for its owner and publishes organization.restored", async () => {
    const tenant = await createTenant("res-owner");
    await remove(tenant);
    const seen = capture("organization.restored");

    const restored = await restoreOrganization(tenant.userIds.owner, tenant.org.id);

    expect(restored.archivedAt).toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      slug: "res-owner",
    });

    const actor = await resolveActorForOrg(principalFor(tenant.userIds.owner), "res-owner");
    expect(actor?.role).toBe("owner");
    const listed = await listOrganizationsForUser(tenant.userIds.member);
    expect(listed.map((org) => org.id)).toEqual([tenant.org.id]);
  });

  it("is not found for strangers, unknown ids and removed members", async () => {
    const tenant = await createTenant("res-stranger");
    const other = await createTenant("res-elsewhere");
    await remove(tenant);

    await expect(
      restoreOrganization(other.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      restoreOrganization(tenant.userIds.owner, "01HZZZNOSUCHORG00000000000" as OrgId),
    ).rejects.toBeInstanceOf(NotFoundError);

    expect((await orgRepo.findOrgById(tenant.org.id))?.archivedAt).not.toBeNull();
  });

  it("is denied to members who are not owners", async () => {
    const tenant = await createTenant("res-roles");
    await remove(tenant);
    const seen = capture("organization.restored");

    for (const role of ["admin", "member", "viewer"] as const) {
      await expect(
        restoreOrganization(tenant.userIds[role], tenant.org.id),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
    }

    expect(seen).toEqual([]);
    expect((await orgRepo.findOrgById(tenant.org.id))?.archivedAt).not.toBeNull();
  });

  it("returns a live workspace unchanged and publishes nothing", async () => {
    const tenant = await createTenant("res-live");
    const seen = capture("organization.restored");

    const same = await restoreOrganization(tenant.userIds.owner, tenant.org.id);

    expect(same).toEqual(await orgRepo.findOrgById(tenant.org.id));
    expect(same.updatedAt).toBe(tenant.org.updatedAt);
    expect(seen).toEqual([]);
  });

  it("is not found once the window has closed, purged or not", async () => {
    const tenant = await createTenant("res-late");
    await remove(tenant);
    const at = await deletedAt(tenant.org.id);

    vi.useFakeTimers();
    vi.setSystemTime(new Date(at.getTime() + WINDOW_MS - 1));
    const restored = await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(restored.archivedAt).toBeNull();

    vi.setSystemTime(at);
    await remove(tenant);
    const again = await deletedAt(tenant.org.id);

    vi.setSystemTime(new Date(again.getTime() + WINDOW_MS));
    await expect(
      restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("is recorded in the audit log together with the deletion", async () => {
    const tenant = await createTenant("res-audit");
    detachers.push(registerActivityListeners());

    await remove(tenant);
    await restoreOrganization(tenant.userIds.owner, tenant.org.id);

    const page = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.deleted", "organization.restored"],
      limit: 25,
      cursor: null,
    });

    expect(page.items.map((event) => event.action).sort()).toEqual([
      "organization.deleted",
      "organization.restored",
    ]);
    for (const event of page.items) {
      expect(event).toMatchObject({
        actorId: tenant.userIds.owner,
        subjectKind: "organization",
        subjectId: tenant.org.id,
      });
    }
  });
});

describe("purging", () => {
  it("removes every trace once the window has closed, and only then", async () => {
    const doomed = await createTenant("purge-me");
    const recent = await createTenant("purge-recent");
    const live = await createTenant("purge-live");
    // No usage counters for `doomed`: the purge must not depend on them.
    await usageRepo.recomputeUsage(recent.org.id);
    await usageRepo.recomputeUsage(live.org.id);
    await notifyOnce(doomed);
    await issueRepo.insertIssue(
      issueInput(doomed.org.id, doomed.project.id),
      doomed.userIds.owner,
      1,
    );
    await sessionRepo.createSession(
      doomed.userIds.owner,
      "purge-session-hash",
      toIsoTimestamp(new Date(Date.now() + 400 * MS_PER_DAY)),
    );
    const session = getDb()
      .$client.prepare("SELECT id FROM sessions WHERE token_hash = ?")
      .get("purge-session-hash") as { id: string };
    await sessionRepo.setActiveOrg(session.id as SessionId, doomed.org.id);

    await remove(doomed);
    const at = await deletedAt(doomed.org.id);
    getDb()
      .$client.prepare("UPDATE organizations SET archived_at = ? WHERE id = ?")
      .run(new Date(at.getTime() + 1_000).toISOString(), recent.org.id);
    const liveBefore = snapshot(live.org.id);
    const recentBefore = snapshot(recent.org.id);

    await runCleanupArchivedJob(new Date(at.getTime() + WINDOW_MS - 1));
    expect(await orgRepo.findOrgById(doomed.org.id)).not.toBeNull();

    await runCleanupArchivedJob(new Date(at.getTime() + WINDOW_MS));

    await expect(orgRepo.findOrgById(doomed.org.id)).resolves.toBeNull();
    expect(Object.values(rowsOf(doomed.org.id)).every((n) => n === 0)).toBe(true);
    expect(snapshot(recent.org.id)).toBe(recentBefore);
    expect(snapshot(live.org.id)).toBe(liveBefore);

    // Accounts survive; the session just has no active workspace any more.
    await expect(userRepo.findUserById(doomed.userIds.owner)).resolves.not.toBeNull();
    const principal = await sessionRepo.findSessionByTokenHash("purge-session-hash");
    expect(principal).toMatchObject({ userId: doomed.userIds.owner, activeOrgId: null });

    await expect(
      restoreOrganization(doomed.userIds.owner, doomed.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const reborn = await createOrganization(doomed.userIds.owner, {
      name: "Reborn",
      slug: "purge-me",
      plan: "free",
    });
    expect(reborn.slug).toBe("purge-me");
    expect(reborn.id).not.toBe(doomed.org.id);
  });
});

async function notifyOnce(tenant: Tenant): Promise<void> {
  const rows = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.member], {
    title: "t",
    body: "b",
    href: "/x",
    actorId: null,
  });
  expect(rows).toHaveLength(1);
}

